<script lang="ts">import type { MasonryLayoutDetail } from '@fex-design/svelte/primitive/masonry';import { MasonryItem,MasonryRoot,MasonryViewport } from '@fex-design/svelte/primitive/masonry';import { masonryItems } from './data';let columns:Record<string,number>=$state({});const layout=(value:MasonryLayoutDetail)=>columns=Object.fromEntries(value.items.map(item=>[String(item.key),item.column+1]))</script>
<MasonryRoot columns={3} gap={16} onLayoutChange={layout}><MasonryViewport>{#each masonryItems.slice(0,9) as item,index(item.id)}<MasonryItem itemKey={item.id} {index}><article class="rounded-md border border-border bg-background p-space-md" style:min-height={`${item.height/2}px`}><strong>{item.title}</strong><p class="mt-2 text-xs text-muted-foreground">输入序号 {index+1} · key {item.id} · 最终第 {columns[item.id]??'…'} 列</p></article></MasonryItem>{/each}</MasonryViewport></MasonryRoot>
